mapper.update:
UPDATE sys_ai_conversation SET turn_key=NULL,busy_until=NULL,last_at=NOW(),
    title=IF(title='',LEFT(#{title},60),title)
WHERE id=#{cid} AND turn_key=#{key}

mapper.select:
SELECT id,role,content,payload,created_at AS createdAt FROM sys_ai_message WHERE conversation_id=#{cid}
AND id < #{before}
ORDER BY id DESC LIMIT #{limit}
